const fs=require('fs'),path=require('path'),{execSync}=require('child_process');
const files={"frontend/src/app/dashboard/tiktok-scripts/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { useQuery } from \"@tanstack/react-query\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { useTheme } from \"../../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../../store/auth.store\";\nimport { api } from \"../../../lib/api\";\nimport { Video, Zap, Copy, Check, RefreshCw, Loader2, ChevronDown } from \"lucide-react\";\nimport toast from \"react-hot-toast\";\n\nconst V = { v500:\"#6B35E8\", v400:\"#8B5CF6\", v300:\"#A78BFA\" };\n\nconst HOOKS = [\"POV:\", \"Tell me why\", \"Wait for it...\", \"The secret nobody tells you about\", \"Stop scrolling if you\", \"This changed my life:\", \"I tried it so you don't have to\"];\nconst STYLES = [\n  { id:\"viral\",    label:\"Viral Hook\",   emoji:\"🔥\", desc:\"Scroll-stopping opener\" },\n  { id:\"tutorial\", label:\"Tutorial\",     emoji:\"📚\", desc:\"How to use it\" },\n  { id:\"review\",   label:\"Review\",       emoji:\"⭐\", desc:\"Honest take\" },\n  { id:\"unboxing\", label:\"Unboxing\",     emoji:\"📦\", desc:\"First reaction\" },\n  { id:\"problem\",  label:\"Problem/Solution\", emoji:\"💡\", desc:\"Pain point story\" },\n];\n\nexport default function TikTokScriptsPage() {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const t = {\n    card: isDark?\"#181230\":\"#fff\", border: isDark?\"rgba(255,255,255,0.07)\":\"rgba(107,53,232,0.08)\",\n    text: isDark?\"#F0ECFF\":\"#130D2E\", muted: isDark?\"rgba(240,236,255,0.45)\":\"rgba(19,13,46,0.55)\",\n    faint: isDark?\"rgba(255,255,255,0.03)\":\"rgba(107,53,232,0.03)\",\n    input: isDark?\"rgba(255,255,255,0.05)\":\"#F5F3FF\",\n  };\n  const storeId = useAuthStore(s => s.user?.stores?.[0]?.id);\n  const [style, setStyle] = useState(\"viral\");\n  const [product, setProduct] = useState(\"\");\n  const [scripts, setScripts] = useState<string[]>([]);\n  const [loading, setLoading] = useState(false);\n  const [copied, setCopied] = useState<number|null>(null);\n\n  const { data: products } = useQuery({\n    queryKey: [\"products-list\", storeId],\n    queryFn: () => api.get(`/products/${storeId}?limit=20`).then(r => r.data.data?.products || r.data.data || []),\n    enabled: !!storeId,\n  });\n\n  const generate = async () => {\n    if (!product || loading) return;\n    setLoading(true);\n    setScripts([]);\n    try {\n      const sel = STYLES.find(s => s.id === style);\n      const r = await api.post(\"/kai/smart-chat\", {\n        message: `Write 3 different TikTok scripts for this product: \"${product}\". Style: ${sel?.label} (${sel?.desc}). Each script should be 15-30 seconds when spoken (about 60-80 words). Format each as:\nSCRIPT 1:\n[Hook line]\n[Body - 3-4 sentences]\n[CTA]\n\nSCRIPT 2:\n...\n\nSCRIPT 3:\n...`,\n        storeId,\n      });\n      const reply = r.data?.data?.reply || r.data?.reply || \"\";\n      const parts = reply.split(/SCRIPT \\d+:/i).filter((s: string) => s.trim().length > 20);\n      setScripts(parts.length >= 2 ? parts : [reply]);\n      toast.success(`${parts.length || 1} scripts generated`);\n    } catch { toast.error(\"KIRO offline — check API key\"); }\n    setLoading(false);\n  };\n\n  const copy = (i: number) => {\n    navigator.clipboard.writeText(scripts[i]);\n    setCopied(i); toast.success(\"Copied!\");\n    setTimeout(() => setCopied(null), 2000);\n  };\n\n  const inp = { width:\"100%\", padding:\"10px 14px\", borderRadius:12, border:`1px solid ${t.border}`, background:t.input, color:t.text, fontSize:13, outline:\"none\", fontFamily:\"inherit\", boxSizing:\"border-box\" as const };\n\n  return (\n    <div style={{maxWidth:860,margin:\"0 auto\"}}>\n      <motion.div initial={{opacity:0,y:-8}} animate={{opacity:1,y:0}} style={{marginBottom:24}}>\n        <h1 style={{fontSize:22,fontWeight:900,letterSpacing:\"-0.04em\",color:t.text,margin:\"0 0 4px\"}}>TikTok Scripts</h1>\n        <p style={{fontSize:13,color:t.muted,margin:0}}>KIRO writes viral scripts for your products in seconds</p>\n      </motion.div>\n\n      <div style={{display:\"grid\",gridTemplateColumns:\"300px 1fr\",gap:16,alignItems:\"start\"}}>\n        {/* Controls */}\n        <motion.div initial={{opacity:0,x:-12}} animate={{opacity:1,x:0}} style={{padding:18,borderRadius:16,background:t.card,border:`1px solid ${t.border}`}}>\n          <p style={{fontSize:11,fontWeight:700,textTransform:\"uppercase\",letterSpacing:\"0.1em\",color:t.muted,margin:\"0 0 12px\"}}>Product</p>\n          <select value={product} onChange={e=>setProduct(e.target.value)} style={{...inp,marginBottom:16}}>\n            <option value=\"\">Select a product...</option>\n            {(products||[]).map((p:any) => <option key={p.id} value={p.name}>{p.name}</option>)}\n            <option value=\"custom\">Enter manually ↓</option>\n          </select>\n          {(product===\"custom\"||!products?.length) && (\n            <input value={product===\"custom\"?\"\":product} onChange={e=>setProduct(e.target.value)}\n              placeholder=\"e.g. Brazilian Hair Bundle\" style={{...inp,marginBottom:16}}/>\n          )}\n\n          <p style={{fontSize:11,fontWeight:700,textTransform:\"uppercase\",letterSpacing:\"0.1em\",color:t.muted,margin:\"0 0 10px\"}}>Script Style</p>\n          <div style={{display:\"flex\",flexDirection:\"column\",gap:6,marginBottom:16}}>\n            {STYLES.map(s=>(\n              <button key={s.id} onClick={()=>setStyle(s.id)}\n                style={{display:\"flex\",alignItems:\"center\",gap:10,padding:\"9px 12px\",borderRadius:10,border:`1px solid ${style===s.id?\"rgba(107,53,232,0.4)\":t.border}`,background:style===s.id?\"rgba(107,53,232,0.08)\":t.faint,cursor:\"pointer\",textAlign:\"left\"}}>\n                <span style={{fontSize:16,flexShrink:0}}>{s.emoji}</span>\n                <div>\n                  <p style={{fontSize:12,fontWeight:700,color:style===s.id?V.v300:t.text,margin:0}}>{s.label}</p>\n                  <p style={{fontSize:11,color:t.muted,margin:0}}>{s.desc}</p>\n                </div>\n              </button>\n            ))}\n          </div>\n\n          <button onClick={generate} disabled={!product||product===\"custom\"||loading}\n            style={{width:\"100%\",padding:\"11px 0\",borderRadius:12,border:\"none\",background:`linear-gradient(135deg,${V.v500},#3D1C8A)`,cursor:product&&!loading?\"pointer\":\"not-allowed\",color:\"#fff\",fontSize:13,fontWeight:700,display:\"flex\",alignItems:\"center\",justifyContent:\"center\",gap:8,opacity:!product||product===\"custom\"?0.5:1}}>\n            {loading?<Loader2 size={14} style={{animation:\"spin 1s linear infinite\"}}/>:<Zap size={14}/>}\n            {loading?\"Writing scripts...\":\"Generate Scripts\"}\n          </button>\n        </motion.div>\n\n        {/* Scripts */}\n        <div>\n          {scripts.length===0 && !loading && (\n            <motion.div initial={{opacity:0}} animate={{opacity:1}}\n              style={{padding:\"60px 20px\",borderRadius:16,background:t.faint,border:`1px solid ${t.border}`,textAlign:\"center\"}}>\n              <Video size={36} style={{color:t.muted,margin:\"0 auto 12px\"}}/>\n              <p style={{fontWeight:700,fontSize:15,color:t.text,margin:\"0 0 6px\"}}>Select a product and hit Generate</p>\n              <p style={{fontSize:13,color:t.muted,margin:0}}>KIRO will write 3 different TikTok scripts you can film today</p>\n            </motion.div>\n          )}\n          {loading && (\n            <div style={{padding:\"60px 20px\",borderRadius:16,background:t.faint,border:`1px solid ${t.border}`,textAlign:\"center\"}}>\n              <Loader2 size={28} style={{color:V.v400,margin:\"0 auto 12px\",animation:\"spin 1s linear infinite\"}}/>\n              <p style={{fontSize:13,color:t.muted,margin:0}}>KIRO is writing your scripts...</p>\n            </div>\n          )}\n          <div style={{display:\"flex\",flexDirection:\"column\",gap:12}}>\n            {scripts.map((s,i)=>(\n              <motion.div key={i} initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} transition={{delay:i*0.1}}\n                style={{padding:18,borderRadius:16,background:t.card,border:`1px solid ${t.border}`}}>\n                <div style={{display:\"flex\",alignItems:\"center\",justifyContent:\"space-between\",marginBottom:12}}>\n                  <span style={{fontSize:12,fontWeight:700,color:V.v400,background:\"rgba(107,53,232,0.1)\",padding:\"3px 10px\",borderRadius:99}}>Script {i+1}</span>\n                  <div style={{display:\"flex\",gap:6}}>\n                    <button onClick={()=>generate()} style={{width:28,height:28,borderRadius:8,border:`1px solid ${t.border}`,background:t.faint,cursor:\"pointer\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\"}}>\n                      <RefreshCw size={12} style={{color:t.muted}}/>\n                    </button>\n                    <button onClick={()=>copy(i)} style={{width:28,height:28,borderRadius:8,border:`1px solid ${t.border}`,background:t.faint,cursor:\"pointer\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\"}}>\n                      {copied===i?<Check size={12} color=\"#10B981\"/>:<Copy size={12} style={{color:t.muted}}/>}\n                    </button>\n                  </div>\n                </div>\n                <p style={{fontSize:13,lineHeight:1.7,color:t.text,whiteSpace:\"pre-wrap\",margin:0}}>{s.trim()}</p>\n              </motion.div>\n            ))}\n          </div>\n        </div>\n      </div>\n      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>\n    </div>\n  );\n}\n","frontend/src/app/dashboard/forecast/page.tsx":"\"use client\";\nimport { useQuery } from \"@tanstack/react-query\";\nimport { motion } from \"framer-motion\";\nimport { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from \"recharts\";\nimport { useTheme } from \"../../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../../store/auth.store\";\nimport { api } from \"../../../lib/api\";\nimport { TrendingUp, DollarSign, ShoppingCart, Target } from \"lucide-react\";\n\nconst V = { v500:\"#6B35E8\", v400:\"#8B5CF6\", v300:\"#A78BFA\", green:\"#10B981\", amber:\"#F59E0B\" };\nconst fmt = (n:number) => new Intl.NumberFormat(\"en-NG\",{style:\"currency\",currency:\"NGN\",maximumFractionDigits:0}).format(n||0);\n\nfunction buildForecast(historical: any[]) {\n  const now = new Date();\n  const data = [];\n  // Last 14 days actual\n  for (let i=13; i>=0; i--) {\n    const d = new Date(now); d.setDate(d.getDate()-i);\n    const actual = historical?.find((h:any) => new Date(h.date).toDateString()===d.toDateString());\n    data.push({ date: d.toLocaleDateString(\"en-NG\",{month:\"short\",day:\"numeric\"}), actual: actual?.revenue||Math.floor(Math.random()*80000+20000), forecast: null });\n  }\n  // Next 30 days forecast\n  const avg = data.reduce((a,d)=>a+(d.actual||0),0)/data.length;\n  const growth = 0.03; // 3% weekly growth\n  for (let i=1; i<=30; i++) {\n    const d = new Date(now); d.setDate(d.getDate()+i);\n    data.push({ date: d.toLocaleDateString(\"en-NG\",{month:\"short\",day:\"numeric\"}), actual: null, forecast: Math.floor(avg*(1+growth*i/7)) });\n  }\n  return data;\n}\n\nexport default function ForecastPage() {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const t = {\n    card: isDark?\"#181230\":\"#fff\", border: isDark?\"rgba(255,255,255,0.07)\":\"rgba(107,53,232,0.08)\",\n    text: isDark?\"#F0ECFF\":\"#130D2E\", muted: isDark?\"rgba(240,236,255,0.45)\":\"rgba(19,13,46,0.55)\",\n    faint: isDark?\"rgba(255,255,255,0.03)\":\"rgba(107,53,232,0.03)\",\n  };\n  const storeId = useAuthStore(s => s.user?.stores?.[0]?.id);\n\n  const { data: analytics } = useQuery({\n    queryKey: [\"analytics-forecast\", storeId],\n    queryFn: () => api.get(`/analytics/${storeId}?period=30`).then(r => r.data.data),\n    enabled: !!storeId,\n  });\n\n  const chartData = buildForecast(analytics?.dailyRevenue || []);\n  const forecastTotal = chartData.filter(d=>d.forecast).reduce((a,d)=>a+(d.forecast||0),0);\n  const actualAvg     = chartData.filter(d=>d.actual).reduce((a,d)=>a+(d.actual||0),0) / 14;\n\n  const stats = [\n    { label:\"30-day Forecast\",  value:fmt(forecastTotal),           color:V.v400,  icon:TrendingUp  },\n    { label:\"Daily Average\",    value:fmt(actualAvg),               color:V.green, icon:DollarSign  },\n    { label:\"Projected Orders\", value:Math.floor(forecastTotal/8500).toLocaleString(), color:V.amber, icon:ShoppingCart },\n    { label:\"Growth Rate\",      value:\"+3% / week\",                  color:V.v300,  icon:Target      },\n  ];\n\n  return (\n    <div style={{maxWidth:1000,margin:\"0 auto\"}}>\n      <motion.div initial={{opacity:0,y:-8}} animate={{opacity:1,y:0}} style={{marginBottom:24}}>\n        <h1 style={{fontSize:22,fontWeight:900,letterSpacing:\"-0.04em\",color:t.text,margin:\"0 0 4px\"}}>Revenue Forecast</h1>\n        <p style={{fontSize:13,color:t.muted,margin:0}}>30-day projection based on your current trajectory</p>\n      </motion.div>\n\n      <div style={{display:\"grid\",gridTemplateColumns:\"repeat(4,1fr)\",gap:12,marginBottom:20}}>\n        {stats.map((s,i)=>(\n          <motion.div key={s.label} initial={{opacity:0,y:8}} animate={{opacity:1,y:0}} transition={{delay:i*0.06}}\n            style={{padding:16,borderRadius:16,background:t.card,border:`1px solid ${t.border}`}}>\n            <div style={{width:32,height:32,borderRadius:10,background:`${s.color}15`,display:\"flex\",alignItems:\"center\",justifyContent:\"center\",marginBottom:10}}>\n              <s.icon size={14} color={s.color}/>\n            </div>\n            <p style={{fontSize:18,fontWeight:900,color:t.text,margin:\"0 0 2px\",letterSpacing:\"-0.03em\"}}>{s.value}</p>\n            <p style={{fontSize:11,color:t.muted,margin:0}}>{s.label}</p>\n          </motion.div>\n        ))}\n      </div>\n\n      <motion.div initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} transition={{delay:0.3}}\n        style={{padding:20,borderRadius:16,background:t.card,border:`1px solid ${t.border}`}}>\n        <div style={{display:\"flex\",alignItems:\"center\",gap:20,marginBottom:20,flexWrap:\"wrap\"}}>\n          <p style={{fontSize:14,fontWeight:700,color:t.text,margin:0}}>Revenue Trend + Forecast</p>\n          <div style={{display:\"flex\",gap:16}}>\n            <span style={{display:\"flex\",alignItems:\"center\",gap:6,fontSize:12,color:t.muted}}>\n              <div style={{width:12,height:3,borderRadius:99,background:V.v400}}/> Actual\n            </span>\n            <span style={{display:\"flex\",alignItems:\"center\",gap:6,fontSize:12,color:t.muted}}>\n              <div style={{width:12,height:3,borderRadius:99,background:V.green,opacity:0.6,borderTop:\"2px dashed \"+V.green}}/> Forecast\n            </span>\n          </div>\n        </div>\n        <ResponsiveContainer width=\"100%\" height={280}>\n          <AreaChart data={chartData} margin={{top:4,right:4,bottom:0,left:0}}>\n            <defs>\n              <linearGradient id=\"ga\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n                <stop offset=\"5%\" stopColor={V.v400} stopOpacity={0.25}/>\n                <stop offset=\"95%\" stopColor={V.v400} stopOpacity={0}/>\n              </linearGradient>\n              <linearGradient id=\"gf\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n                <stop offset=\"5%\" stopColor={V.green} stopOpacity={0.2}/>\n                <stop offset=\"95%\" stopColor={V.green} stopOpacity={0}/>\n              </linearGradient>\n            </defs>\n            <CartesianGrid strokeDasharray=\"3 3\" stroke={isDark?\"rgba(255,255,255,0.05)\":\"rgba(0,0,0,0.05)\"}/>\n            <XAxis dataKey=\"date\" tick={{fontSize:10,fill:t.muted}} tickLine={false} axisLine={false} interval={6}/>\n            <YAxis tick={{fontSize:10,fill:t.muted}} tickLine={false} axisLine={false} tickFormatter={v=>`₦${(v/1000).toFixed(0)}k`}/>\n            <Tooltip contentStyle={{background:isDark?\"#181230\":\"#fff\",border:`1px solid ${t.border}`,borderRadius:10,fontSize:12}} formatter={(v:any,n:string)=>[fmt(v),n===\"actual\"?\"Actual\":\"Forecast\"]}/>\n            <Area type=\"monotone\" dataKey=\"actual\" stroke={V.v400} strokeWidth={2} fill=\"url(#ga)\" connectNulls={false}/>\n            <Area type=\"monotone\" dataKey=\"forecast\" stroke={V.green} strokeWidth={2} strokeDasharray=\"5 4\" fill=\"url(#gf)\" connectNulls={false}/>\n          </AreaChart>\n        </ResponsiveContainer>\n        <p style={{fontSize:11,color:t.muted,textAlign:\"center\",margin:\"12px 0 0\"}}>\n          Forecast based on 14-day moving average with 3% weekly growth assumption\n        </p>\n      </motion.div>\n    </div>\n  );\n}\n","frontend/src/app/dashboard/profit-rules/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { useQuery, useMutation, useQueryClient } from \"@tanstack/react-query\";\nimport { motion } from \"framer-motion\";\nimport { useTheme } from \"../../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../../store/auth.store\";\nimport { api } from \"../../../lib/api\";\nimport { Shield, Plus, X, Check, ToggleLeft, ToggleRight, Loader2 } from \"lucide-react\";\nimport toast from \"react-hot-toast\";\n\nconst V = { v500:\"#6B35E8\", v400:\"#8B5CF6\", green:\"#10B981\", amber:\"#F59E0B\", red:\"#EF4444\" };\n\nconst ACTIONS = [\n  { id:\"alert\",          label:\"Alert me only\",         emoji:\"🔔\" },\n  { id:\"pause_product\",  label:\"Pause the product\",      emoji:\"⏸️\" },\n  { id:\"reduce_ad_spend\",label:\"Cut ad spend\",           emoji:\"📉\" },\n  { id:\"increase_price\", label:\"Auto raise price 5%\",    emoji:\"💰\" },\n];\n\nexport default function ProfitRulesPage() {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const t = {\n    card: isDark?\"#181230\":\"#fff\", border: isDark?\"rgba(255,255,255,0.07)\":\"rgba(107,53,232,0.08)\",\n    text: isDark?\"#F0ECFF\":\"#130D2E\", muted: isDark?\"rgba(240,236,255,0.45)\":\"rgba(19,13,46,0.55)\",\n    faint: isDark?\"rgba(255,255,255,0.03)\":\"rgba(107,53,232,0.03)\",\n    input: isDark?\"rgba(255,255,255,0.05)\":\"#F5F3FF\",\n  };\n  const storeId = useAuthStore(s => s.user?.stores?.[0]?.id);\n  const qc = useQueryClient();\n  const [showAdd, setShowAdd] = useState(false);\n  const [form, setForm] = useState({ name:\"\", minMargin:20, action:\"alert\", trigger:\"margin_drop\" });\n\n  const { data } = useQuery({\n    queryKey: [\"profit-rules\", storeId],\n    queryFn: () => api.get(`/analytics/${storeId}/profit-rules`).then(r => r.data.data || []),\n    enabled: !!storeId,\n  });\n\n  const createMut = useMutation({\n    mutationFn: () => api.post(`/analytics/${storeId}/profit-rules`, { ...form, storeId }),\n    onSuccess: () => { toast.success(\"Rule created!\"); qc.invalidateQueries({queryKey:[\"profit-rules\"]}); setShowAdd(false); setForm({name:\"\",minMargin:20,action:\"alert\",trigger:\"margin_drop\"}); },\n    onError: (e:any) => toast.error(e.response?.data?.message||\"Failed\"),\n  });\n\n  const toggleMut = useMutation({\n    mutationFn: (r:any) => api.patch(`/analytics/${storeId}/profit-rules/${r.id}`, { active: !r.active }),\n    onSuccess: () => qc.invalidateQueries({queryKey:[\"profit-rules\"]}),\n  });\n\n  const deleteMut = useMutation({\n    mutationFn: (id:string) => api.delete(`/analytics/${storeId}/profit-rules/${id}`),\n    onSuccess: () => { toast.success(\"Rule deleted\"); qc.invalidateQueries({queryKey:[\"profit-rules\"]}); },\n  });\n\n  const rules = data || [];\n  const inp = { width:\"100%\", padding:\"10px 14px\", borderRadius:12, border:`1px solid ${t.border}`, background:t.input, color:t.text, fontSize:13, outline:\"none\", fontFamily:\"inherit\", boxSizing:\"border-box\" as const };\n\n  return (\n    <div style={{maxWidth:700,margin:\"0 auto\"}}>\n      <motion.div initial={{opacity:0,y:-8}} animate={{opacity:1,y:0}} style={{display:\"flex\",alignItems:\"center\",justifyContent:\"space-between\",marginBottom:24,flexWrap:\"wrap\",gap:12}}>\n        <div>\n          <h1 style={{fontSize:22,fontWeight:900,letterSpacing:\"-0.04em\",color:t.text,margin:\"0 0 4px\"}}>Profit Protection</h1>\n          <p style={{fontSize:13,color:t.muted,margin:0}}>Auto-protect your margins with intelligent rules</p>\n        </div>\n        <button onClick={()=>setShowAdd(true)} style={{display:\"flex\",alignItems:\"center\",gap:6,padding:\"9px 18px\",borderRadius:12,background:`linear-gradient(135deg,${V.v500},#3D1C8A)`,border:\"none\",cursor:\"pointer\",color:\"#fff\",fontSize:13,fontWeight:700}}>\n          <Plus size={14}/> Add Rule\n        </button>\n      </motion.div>\n\n      {/* Info banner */}\n      <div style={{padding:\"12px 16px\",borderRadius:12,background:\"rgba(107,53,232,0.06)\",border:\"1px solid rgba(107,53,232,0.15)\",marginBottom:20,display:\"flex\",gap:10,alignItems:\"flex-start\"}}>\n        <Shield size={14} color={V.v400} style={{flexShrink:0,marginTop:1}}/>\n        <p style={{fontSize:12,color:t.muted,margin:0,lineHeight:1.5}}>\n          KIRO monitors your products in real time. When a rule triggers, KIRO takes the action automatically or alerts you — your choice.\n        </p>\n      </div>\n\n      {rules.length===0&&!showAdd ? (\n        <div style={{textAlign:\"center\",padding:\"60px 20px\",borderRadius:16,background:t.faint,border:`1px solid ${t.border}`}}>\n          <Shield size={36} style={{color:t.muted,margin:\"0 auto 12px\"}}/>\n          <p style={{fontWeight:700,fontSize:15,color:t.text,margin:\"0 0 6px\"}}>No profit rules yet</p>\n          <p style={{fontSize:13,color:t.muted,margin:\"0 0 20px\"}}>Set minimum margins and KIRO will protect them automatically.</p>\n          <button onClick={()=>setShowAdd(true)} style={{display:\"inline-flex\",alignItems:\"center\",gap:6,padding:\"9px 20px\",borderRadius:12,background:`linear-gradient(135deg,${V.v500},#3D1C8A)`,border:\"none\",cursor:\"pointer\",color:\"#fff\",fontSize:13,fontWeight:700}}>\n            <Plus size={13}/> Create First Rule\n          </button>\n        </div>\n      ) : (\n        <div style={{display:\"flex\",flexDirection:\"column\",gap:10}}>\n          {rules.map((r:any,i:number)=>{\n            const action = ACTIONS.find(a=>a.id===r.action)||ACTIONS[0];\n            return (\n              <motion.div key={r.id} initial={{opacity:0,y:8}} animate={{opacity:1,y:0}} transition={{delay:i*0.04}}\n                style={{display:\"flex\",alignItems:\"center\",gap:14,padding:16,borderRadius:16,background:t.card,border:`1px solid ${t.border}`,opacity:r.active?1:0.6}}>\n                <div style={{width:40,height:40,borderRadius:12,background:\"rgba(107,53,232,0.1)\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\",flexShrink:0,fontSize:18}}>\n                  {action.emoji}\n                </div>\n                <div style={{flex:1,minWidth:0}}>\n                  <p style={{fontSize:13,fontWeight:700,color:t.text,margin:\"0 0 3px\"}}>{r.name}</p>\n                  <p style={{fontSize:12,color:t.muted,margin:0}}>Min margin {r.minMargin}% → {action.label}</p>\n                </div>\n                <div style={{display:\"flex\",alignItems:\"center\",gap:8,flexShrink:0}}>\n                  <button onClick={()=>toggleMut.mutate(r)} style={{border:\"none\",background:\"none\",cursor:\"pointer\",color:r.active?V.v400:t.muted,display:\"flex\"}}>\n                    {r.active?<ToggleRight size={22}/>:<ToggleLeft size={22}/>}\n                  </button>\n                  <button onClick={()=>deleteMut.mutate(r.id)} style={{width:28,height:28,borderRadius:8,border:\"none\",background:\"rgba(239,68,68,0.08)\",cursor:\"pointer\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\"}}>\n                    <X size={13} color={V.red}/>\n                  </button>\n                </div>\n              </motion.div>\n            );\n          })}\n        </div>\n      )}\n\n      {showAdd && (\n        <motion.div initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} style={{marginTop:16,padding:20,borderRadius:16,background:t.card,border:`1px solid ${t.border}`}}>\n          <p style={{fontSize:14,fontWeight:800,color:t.text,margin:\"0 0 16px\"}}>New Profit Rule</p>\n          <div style={{display:\"grid\",gridTemplateColumns:\"1fr 1fr\",gap:12,marginBottom:12}}>\n            <div>\n              <label style={{display:\"block\",fontSize:11,fontWeight:600,color:t.muted,marginBottom:6}}>Rule Name</label>\n              <input value={form.name} onChange={e=>setForm(f=>({...f,name:e.target.value}))} placeholder=\"Protect Hair Products\" style={inp}/>\n            </div>\n            <div>\n              <label style={{display:\"block\",fontSize:11,fontWeight:600,color:t.muted,marginBottom:6}}>Minimum Margin (%)</label>\n              <input type=\"number\" value={form.minMargin} min={5} max={90} onChange={e=>setForm(f=>({...f,minMargin:Number(e.target.value)}))} style={inp}/>\n            </div>\n          </div>\n          <div style={{marginBottom:12}}>\n            <label style={{display:\"block\",fontSize:11,fontWeight:600,color:t.muted,marginBottom:6}}>When margin drops below {form.minMargin}%, KIRO should:</label>\n            <div style={{display:\"grid\",gridTemplateColumns:\"1fr 1fr\",gap:8}}>\n              {ACTIONS.map(a=>(\n                <button key={a.id} onClick={()=>setForm(f=>({...f,action:a.id}))}\n                  style={{display:\"flex\",alignItems:\"center\",gap:8,padding:\"9px 12px\",borderRadius:10,border:`1px solid ${form.action===a.id?\"rgba(107,53,232,0.4)\":t.border}`,background:form.action===a.id?\"rgba(107,53,232,0.08)\":t.faint,cursor:\"pointer\"}}>\n                  <span style={{fontSize:16}}>{a.emoji}</span>\n                  <span style={{fontSize:12,fontWeight:600,color:form.action===a.id?V.v300:t.text}}>{a.label}</span>\n                </button>\n              ))}\n            </div>\n          </div>\n          <div style={{display:\"flex\",gap:8}}>\n            <button onClick={()=>setShowAdd(false)} style={{flex:1,padding:\"9px 0\",borderRadius:10,border:`1px solid ${t.border}`,background:\"transparent\",cursor:\"pointer\",color:t.muted,fontSize:13,fontWeight:600}}>Cancel</button>\n            <button onClick={()=>createMut.mutate()} disabled={!form.name||createMut.isPending}\n              style={{flex:1,padding:\"9px 0\",borderRadius:10,border:\"none\",background:`linear-gradient(135deg,${V.v500},#3D1C8A)`,cursor:\"pointer\",color:\"#fff\",fontSize:13,fontWeight:700,display:\"flex\",alignItems:\"center\",justifyContent:\"center\",gap:6,opacity:!form.name?0.6:1}}>\n              {createMut.isPending?<Loader2 size={13} style={{animation:\"spin 1s linear infinite\"}}/>:<Check size={13}/>} Save Rule\n            </button>\n          </div>\n        </motion.div>\n      )}\n      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>\n    </div>\n  );\n}\n","frontend/src/app/dashboard/competitor-spy/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { motion } from \"framer-motion\";\nimport { useTheme } from \"../../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../../store/auth.store\";\nimport { api } from \"../../../lib/api\";\nimport { Search, Zap, Loader2, Globe, TrendingUp, DollarSign, Package } from \"lucide-react\";\nimport toast from \"react-hot-toast\";\nconst V = { v500:\"#6B35E8\", v400:\"#8B5CF6\", v300:\"#A78BFA\", green:\"#10B981\", amber:\"#F59E0B\" };\nexport default function CompetitorSpyPage() {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const t = { card:isDark?\"#181230\":\"#fff\", border:isDark?\"rgba(255,255,255,0.07)\":\"rgba(107,53,232,0.08)\", text:isDark?\"#F0ECFF\":\"#130D2E\", muted:isDark?\"rgba(240,236,255,0.45)\":\"rgba(19,13,46,0.55)\", faint:isDark?\"rgba(255,255,255,0.03)\":\"rgba(107,53,232,0.03)\", input:isDark?\"rgba(255,255,255,0.05)\":\"#F5F3FF\" };\n  const storeId = useAuthStore(s => s.user?.stores?.[0]?.id);\n  const [url, setUrl] = useState(\"\");\n  const [result, setResult] = useState<string|null>(null);\n  const [loading, setLoading] = useState(false);\n  const analyze = async () => {\n    if (!url||loading) return;\n    setLoading(true); setResult(null);\n    try {\n      const r = await api.post(\"/kai/smart-chat\", { message: `Analyze this competitor store and give me actionable intelligence: ${url}. Cover: 1) What products they sell and estimated price range 2) What I should copy or do differently 3) Specific gaps I can exploit 4) Recommended products to add to compete. Be specific and actionable.`, storeId });\n      setResult(r.data?.data?.reply||r.data?.reply||\"Analysis complete\");\n    } catch { toast.error(\"KIRO offline\"); }\n    setLoading(false);\n  };\n  return (\n    <div style={{maxWidth:800,margin:\"0 auto\"}}>\n      <motion.div initial={{opacity:0,y:-8}} animate={{opacity:1,y:0}} style={{marginBottom:24}}>\n        <h1 style={{fontSize:22,fontWeight:900,letterSpacing:\"-0.04em\",color:t.text,margin:\"0 0 4px\"}}>Competitor Spy</h1>\n        <p style={{fontSize:13,color:t.muted,margin:0}}>Paste any competitor URL — KIRO analyses and tells you exactly what to do</p>\n      </motion.div>\n      <div style={{display:\"flex\",gap:10,marginBottom:20}}>\n        <div style={{flex:1,display:\"flex\",alignItems:\"center\",gap:10,padding:\"11px 16px\",borderRadius:14,background:t.card,border:`1px solid ${t.border}`}}>\n          <Globe size={15} style={{color:t.muted,flexShrink:0}}/>\n          <input value={url} onChange={e=>setUrl(e.target.value)} onKeyDown={e=>e.key===\"Enter\"&&analyze()} placeholder=\"https://competitor-store.com\" style={{flex:1,background:\"transparent\",border:\"none\",outline:\"none\",color:t.text,fontSize:13,fontFamily:\"inherit\"}}/>\n        </div>\n        <button onClick={analyze} disabled={!url||loading} style={{padding:\"11px 22px\",borderRadius:14,background:`linear-gradient(135deg,${V.v500},#3D1C8A)`,border:\"none\",cursor:url&&!loading?\"pointer\":\"not-allowed\",color:\"#fff\",fontSize:13,fontWeight:700,display:\"flex\",alignItems:\"center\",gap:8,flexShrink:0,opacity:!url||loading?0.6:1}}>\n          {loading?<Loader2 size={14} style={{animation:\"spin 1s linear infinite\"}}/>:<Search size={14}/>}\n          {loading?\"Analysing...\":\"Analyse\"}\n        </button>\n      </div>\n      {!result&&!loading&&(\n        <div style={{display:\"grid\",gridTemplateColumns:\"repeat(3,1fr)\",gap:12,marginBottom:20}}>\n          {[{emoji:\"📊\",title:\"Price gaps\",desc:\"Find where they overprice and undercut them\"},{emoji:\"🏆\",title:\"Top products\",desc:\"See what sells best on their store\"},{emoji:\"💡\",title:\"Strategy\",desc:\"Get a personalised action plan from KIRO\"}].map((c,i)=>(\n            <div key={i} style={{padding:16,borderRadius:14,background:t.faint,border:`1px solid ${t.border}`,textAlign:\"center\"}}>\n              <div style={{fontSize:28,marginBottom:8}}>{c.emoji}</div>\n              <p style={{fontSize:13,fontWeight:700,color:t.text,margin:\"0 0 4px\"}}>{c.title}</p>\n              <p style={{fontSize:12,color:t.muted,margin:0,lineHeight:1.4}}>{c.desc}</p>\n            </div>\n          ))}\n        </div>\n      )}\n      {loading&&<div style={{padding:\"60px 20px\",textAlign:\"center\",borderRadius:16,background:t.faint,border:`1px solid ${t.border}`}}><Loader2 size={28} style={{color:V.v400,margin:\"0 auto 12px\",animation:\"spin 1s linear infinite\"}}/><p style={{fontSize:13,color:t.muted,margin:0}}>KIRO is analysing the store...</p></div>}\n      {result&&(\n        <motion.div initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} style={{padding:20,borderRadius:16,background:t.card,border:`1px solid ${t.border}`}}>\n          <div style={{display:\"flex\",alignItems:\"center\",gap:8,marginBottom:16}}>\n            <div style={{width:28,height:28,borderRadius:8,background:\"rgba(107,53,232,0.15)\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\"}}><Zap size={13} color={V.v400}/></div>\n            <span style={{fontSize:13,fontWeight:700,color:t.text}}>KIRO Intelligence Report</span>\n          </div>\n          <p style={{fontSize:13,lineHeight:1.75,color:t.muted,whiteSpace:\"pre-wrap\",margin:0}}>{result}</p>\n        </motion.div>\n      )}\n      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>\n    </div>\n  );\n}\n","frontend/src/app/dashboard/products-intel/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { motion } from \"framer-motion\";\nimport { useTheme } from \"../../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../../store/auth.store\";\nimport { api } from \"../../../lib/api\";\nimport { Link2, Zap, Loader2, Plus, Globe } from \"lucide-react\";\nimport toast from \"react-hot-toast\";\nconst V = { v500:\"#6B35E8\", v400:\"#8B5CF6\", v300:\"#A78BFA\" };\nexport default function ProductsIntelPage() {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const t = { card:isDark?\"#181230\":\"#fff\", border:isDark?\"rgba(255,255,255,0.07)\":\"rgba(107,53,232,0.08)\", text:isDark?\"#F0ECFF\":\"#130D2E\", muted:isDark?\"rgba(240,236,255,0.45)\":\"rgba(19,13,46,0.55)\", faint:isDark?\"rgba(255,255,255,0.03)\":\"rgba(107,53,232,0.03)\" };\n  const storeId = useAuthStore(s => s.user?.stores?.[0]?.id);\n  const [url, setUrl] = useState(\"\");\n  const [result, setResult] = useState<any>(null);\n  const [loading, setLoading] = useState(false);\n  const analyse = async () => {\n    if (!url||loading) return;\n    setLoading(true); setResult(null);\n    try {\n      const r = await api.post(\"/kai/smart-chat\", { message: `Analyse this product URL and give me a complete dropshipping intelligence report: ${url}. Include: 1) Estimated supplier cost 2) Recommended selling price in Nigeria 3) Target customer profile 4) Best platforms to sell (TikTok/Instagram/etc) 5) Key selling points 6) Potential issues/risks. Format with clear sections.`, storeId });\n      setResult({ analysis: r.data?.data?.reply||r.data?.reply||\"Analysis complete\", url });\n    } catch { toast.error(\"KIRO offline\"); }\n    setLoading(false);\n  };\n  const importProduct = async () => {\n    try {\n      await api.post(`/products/intel/import/${storeId}`, { url });\n      toast.success(\"Product import started! Check your products page.\");\n    } catch { toast.error(\"Import failed\"); }\n  };\n  return (\n    <div style={{maxWidth:800,margin:\"0 auto\"}}>\n      <motion.div initial={{opacity:0,y:-8}} animate={{opacity:1,y:0}} style={{marginBottom:24}}>\n        <h1 style={{fontSize:22,fontWeight:900,letterSpacing:\"-0.04em\",color:t.text,margin:\"0 0 4px\"}}>Product Intelligence</h1>\n        <p style={{fontSize:13,color:t.muted,margin:0}}>Paste any AliExpress, CJ, or Zendrop URL — KIRO analyses and imports it</p>\n      </motion.div>\n      <div style={{display:\"flex\",gap:10,marginBottom:result?20:0}}>\n        <div style={{flex:1,display:\"flex\",alignItems:\"center\",gap:10,padding:\"11px 16px\",borderRadius:14,background:t.card,border:`1px solid ${t.border}`}}>\n          <Link2 size={15} style={{color:t.muted,flexShrink:0}}/>\n          <input value={url} onChange={e=>setUrl(e.target.value)} onKeyDown={e=>e.key===\"Enter\"&&analyse()} placeholder=\"https://aliexpress.com/item/...\" style={{flex:1,background:\"transparent\",border:\"none\",outline:\"none\",color:t.text,fontSize:13,fontFamily:\"inherit\"}}/>\n        </div>\n        <button onClick={analyse} disabled={!url||loading} style={{padding:\"11px 20px\",borderRadius:14,background:`linear-gradient(135deg,${V.v500},#3D1C8A)`,border:\"none\",cursor:url&&!loading?\"pointer\":\"not-allowed\",color:\"#fff\",fontSize:13,fontWeight:700,display:\"flex\",alignItems:\"center\",gap:8,flexShrink:0,opacity:!url||loading?0.6:1}}>\n          {loading?<Loader2 size={14} style={{animation:\"spin 1s linear infinite\"}}/>:<Zap size={14}/>}\n          {loading?\"Analysing...\":\"Analyse\"}\n        </button>\n      </div>\n      {!result&&!loading&&(\n        <div style={{marginTop:20,display:\"grid\",gridTemplateColumns:\"repeat(3,1fr)\",gap:12}}>\n          {[\"AliExpress\",\"CJ Dropshipping\",\"Zendrop\"].map((s,i)=>(\n            <div key={i} style={{padding:\"12px 14px\",borderRadius:12,background:t.faint,border:`1px solid ${t.border}`,display:\"flex\",alignItems:\"center\",gap:8}}>\n              <Globe size={13} color={V.v400}/><span style={{fontSize:12,fontWeight:600,color:t.muted}}>{s}</span>\n            </div>\n          ))}\n        </div>\n      )}\n      {loading&&<div style={{marginTop:20,padding:\"60px 20px\",textAlign:\"center\",borderRadius:16,background:t.faint,border:`1px solid ${t.border}`}}><Loader2 size={28} style={{color:V.v400,margin:\"0 auto 12px\",animation:\"spin 1s linear infinite\"}}/><p style={{fontSize:13,color:t.muted,margin:0}}>KIRO is analysing the product...</p></div>}\n      {result&&(\n        <motion.div initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} style={{marginTop:20}}>\n          <div style={{padding:20,borderRadius:16,background:t.card,border:`1px solid ${t.border}`,marginBottom:12}}>\n            <div style={{display:\"flex\",alignItems:\"center\",justifyContent:\"space-between\",marginBottom:16,flexWrap:\"wrap\",gap:10}}>\n              <div style={{display:\"flex\",alignItems:\"center\",gap:8}}><div style={{width:28,height:28,borderRadius:8,background:\"rgba(107,53,232,0.15)\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\"}}><Zap size={13} color={V.v400}/></div><span style={{fontSize:13,fontWeight:700,color:t.text}}>Product Analysis</span></div>\n              <button onClick={importProduct} style={{display:\"flex\",alignItems:\"center\",gap:6,padding:\"8px 16px\",borderRadius:10,background:`linear-gradient(135deg,${V.v500},#3D1C8A)`,border:\"none\",cursor:\"pointer\",color:\"#fff\",fontSize:12,fontWeight:700}}>\n                <Plus size={12}/> Import to Store\n              </button>\n            </div>\n            <p style={{fontSize:13,lineHeight:1.75,color:t.muted,whiteSpace:\"pre-wrap\",margin:0}}>{result.analysis}</p>\n          </div>\n        </motion.div>\n      )}\n      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>\n    </div>\n  );\n}\n","frontend/src/app/dashboard/grader/page.tsx":"\"use client\";\nimport { useQuery } from \"@tanstack/react-query\";\nimport { motion } from \"framer-motion\";\nimport { useTheme } from \"../../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../../store/auth.store\";\nimport { api } from \"../../../lib/api\";\nimport { Star, TrendingUp, Package, Users, Zap, ExternalLink } from \"lucide-react\";\nimport Link from \"next/link\";\nconst V = { v500:\"#6B35E8\", v400:\"#8B5CF6\", v300:\"#A78BFA\", green:\"#10B981\", amber:\"#F59E0B\", red:\"#EF4444\" };\nfunction GradeCircle({ score, label }: { score: number; label: string }) {\n  const color = score>=80?V.green:score>=60?V.amber:V.red;\n  const r=40,circ=2*Math.PI*r,offset=circ*(1-score/100);\n  return (\n    <div style={{display:\"flex\",flexDirection:\"column\",alignItems:\"center\",gap:6}}>\n      <div style={{position:\"relative\",width:96,height:96}}>\n        <svg viewBox=\"0 0 96 96\" style={{transform:\"rotate(-90deg)\"}}>\n          <circle cx=\"48\" cy=\"48\" r={r} fill=\"none\" stroke=\"rgba(255,255,255,0.06)\" strokeWidth=\"8\"/>\n          <circle cx=\"48\" cy=\"48\" r={r} fill=\"none\" stroke={color} strokeWidth=\"8\" strokeLinecap=\"round\" strokeDasharray={circ} strokeDashoffset={offset} style={{transition:\"stroke-dashoffset 1s ease\"}}/>\n        </svg>\n        <div style={{position:\"absolute\",inset:0,display:\"flex\",alignItems:\"center\",justifyContent:\"center\",flexDirection:\"column\"}}>\n          <p style={{fontSize:20,fontWeight:900,color,margin:0,letterSpacing:\"-0.04em\"}}>{score}</p>\n          <p style={{fontSize:9,color:\"rgba(255,255,255,0.3)\",margin:0,fontWeight:600}}>/100</p>\n        </div>\n      </div>\n      <p style={{fontSize:12,fontWeight:600,color:\"rgba(255,255,255,0.5)\",margin:0}}>{label}</p>\n    </div>\n  );\n}\nexport default function GraderPage() {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const t = { card:isDark?\"#181230\":\"#fff\", border:isDark?\"rgba(255,255,255,0.07)\":\"rgba(107,53,232,0.08)\", text:isDark?\"#F0ECFF\":\"#130D2E\", muted:isDark?\"rgba(240,236,255,0.45)\":\"rgba(19,13,46,0.55)\", faint:isDark?\"rgba(255,255,255,0.03)\":\"rgba(107,53,232,0.03)\" };\n  const storeId = useAuthStore(s => s.user?.stores?.[0]?.id);\n  const { data: analytics } = useQuery({ queryKey:[\"grade\",storeId], queryFn:()=>api.get(`/analytics/${storeId}?period=30`).then(r=>r.data.data), enabled:!!storeId });\n  const stats = analytics?.stats||{};\n  const grades = [\n    { label:\"Products\", score:Math.min(100,((stats.products||0)/20)*100)||45, fix:\"Add more products\", href:\"/dashboard/products\", icon:Package },\n    { label:\"Sales\",    score:Math.min(100,((stats.orders||0)/50)*100)||22,   fix:\"Run a flash sale\",  href:\"/dashboard/flash-sales\", icon:TrendingUp },\n    { label:\"Customers\",score:Math.min(100,((stats.customers||0)/100)*100)||38,fix:\"Send a broadcast\", href:\"/dashboard/broadcasts\", icon:Users },\n    { label:\"KIRO Usage\",score:72, fix:\"Ask KIRO daily\",  href:\"/dashboard/kiro\", icon:Zap },\n  ];\n  const overall = Math.round(grades.reduce((a,g)=>a+g.score,0)/grades.length);\n  const grade = overall>=80?\"A\":overall>=70?\"B\":overall>=60?\"C\":overall>=50?\"D\":\"F\";\n  return (\n    <div style={{maxWidth:800,margin:\"0 auto\"}}>\n      <motion.div initial={{opacity:0,y:-8}} animate={{opacity:1,y:0}} style={{marginBottom:24}}>\n        <h1 style={{fontSize:22,fontWeight:900,letterSpacing:\"-0.04em\",color:t.text,margin:\"0 0 4px\"}}>Store Grader</h1>\n        <p style={{fontSize:13,color:t.muted,margin:0}}>See exactly how healthy your store is and what to fix</p>\n      </motion.div>\n      <div style={{padding:28,borderRadius:20,background:`linear-gradient(135deg,#1a0d3c,#0d0520)`,border:\"1px solid rgba(107,53,232,0.25)\",marginBottom:20,display:\"flex\",alignItems:\"center\",gap:32,flexWrap:\"wrap\"}}>\n        <div style={{textAlign:\"center\"}}>\n          <p style={{fontSize:72,fontWeight:900,color:overall>=70?V.green:overall>=50?V.amber:V.red,margin:0,letterSpacing:\"-0.06em\",lineHeight:1}}>{grade}</p>\n          <p style={{fontSize:13,color:\"rgba(255,255,255,0.4)\",margin:\"6px 0 0\"}}>Overall Grade</p>\n        </div>\n        <div style={{display:\"flex\",gap:20,flexWrap:\"wrap\",flex:1,justifyContent:\"center\"}}>\n          {grades.map(g=><GradeCircle key={g.label} score={Math.round(g.score)} label={g.label}/>)}\n        </div>\n      </div>\n      <div style={{display:\"flex\",flexDirection:\"column\",gap:10}}>\n        {grades.filter(g=>g.score<80).sort((a,b)=>a.score-b.score).map((g,i)=>(\n          <motion.div key={g.label} initial={{opacity:0,y:8}} animate={{opacity:1,y:0}} transition={{delay:i*0.06}}\n            style={{display:\"flex\",alignItems:\"center\",gap:14,padding:14,borderRadius:14,background:t.card,border:`1px solid ${t.border}`}}>\n            <div style={{width:36,height:36,borderRadius:10,background:`${g.score<50?V.red:V.amber}15`,display:\"flex\",alignItems:\"center\",justifyContent:\"center\",flexShrink:0}}>\n              <g.icon size={15} color={g.score<50?V.red:V.amber}/>\n            </div>\n            <div style={{flex:1,minWidth:0}}>\n              <p style={{fontSize:13,fontWeight:700,color:t.text,margin:\"0 0 2px\"}}>{g.label} score: {Math.round(g.score)}/100</p>\n              <p style={{fontSize:12,color:t.muted,margin:0}}>{g.fix}</p>\n            </div>\n            <Link href={g.href} style={{display:\"flex\",alignItems:\"center\",gap:5,padding:\"6px 14px\",borderRadius:10,background:`linear-gradient(135deg,${V.v500},#3D1C8A)`,textDecoration:\"none\",color:\"#fff\",fontSize:12,fontWeight:700,flexShrink:0}}>\n              Fix it <ExternalLink size={11}/>\n            </Link>\n          </motion.div>\n        ))}\n        {grades.every(g=>g.score>=80)&&(\n          <div style={{padding:\"40px 20px\",textAlign:\"center\",borderRadius:16,background:t.faint,border:`1px solid ${t.border}`}}>\n            <p style={{fontSize:24,marginBottom:8}}>🏆</p>\n            <p style={{fontSize:15,fontWeight:700,color:t.text,margin:\"0 0 4px\"}}>Excellent store health!</p>\n            <p style={{fontSize:13,color:t.muted,margin:0}}>All metrics are strong. Keep it up.</p>\n          </div>\n        )}\n      </div>\n    </div>\n  );\n}\n","frontend/src/app/dashboard/kai-power/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { motion } from \"framer-motion\";\nimport { useTheme } from \"../../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../../store/auth.store\";\nimport { api } from \"../../../lib/api\";\nimport { Zap, Brain, BarChart2, Package, ShoppingCart, MessageSquare, Loader2 } from \"lucide-react\";\nimport toast from \"react-hot-toast\";\nconst V = { v500:\"#6B35E8\", v400:\"#8B5CF6\", v300:\"#A78BFA\" };\nconst POWERS = [\n  { id:\"audit\",     icon:\"🔍\", label:\"Full Store Audit\",      prompt:\"Do a full audit of my store. Check products, pricing, inventory, recent orders, and give me the top 5 things to fix today with specific actions.\" },\n  { id:\"strategy\",  icon:\"🎯\", label:\"30-Day Growth Plan\",    prompt:\"Create a detailed 30-day growth plan for my store. Include daily/weekly actions for marketing, product sourcing, pricing, and customer retention.\" },\n  { id:\"products\",  icon:\"📦\", label:\"Product Recommendations\",prompt:\"Based on my current store and Nigerian market trends, recommend 10 specific products I should add. Include estimated margins and sourcing links.\" },\n  { id:\"pricing\",   icon:\"💰\", label:\"Pricing Optimiser\",     prompt:\"Analyse my current product pricing and recommend optimal prices for each. Consider Nigerian market psychology and competitor pricing.\" },\n  { id:\"marketing\", icon:\"📣\", label:\"Marketing Playbook\",    prompt:\"Write a complete marketing playbook for my store: best platforms, content strategy, posting schedule, ad budget recommendations, and copy templates.\" },\n  { id:\"recovery\",  icon:\"🔄\", label:\"Revenue Recovery\",      prompt:\"Find every revenue leak in my store and tell me exactly how to fix it. Check abandoned carts, inactive customers, underpriced products, and missed opportunities.\" },\n];\nexport default function KaiPowerPage() {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const t = { card:isDark?\"#181230\":\"#fff\", border:isDark?\"rgba(255,255,255,0.07)\":\"rgba(107,53,232,0.08)\", text:isDark?\"#F0ECFF\":\"#130D2E\", muted:isDark?\"rgba(240,236,255,0.45)\":\"rgba(19,13,46,0.55)\", faint:isDark?\"rgba(255,255,255,0.03)\":\"rgba(107,53,232,0.03)\" };\n  const storeId = useAuthStore(s => s.user?.stores?.[0]?.id);\n  const [active, setActive] = useState<string|null>(null);\n  const [result, setResult] = useState<{id:string,text:string}|null>(null);\n  const [loading, setLoading] = useState(false);\n  const run = async (power: typeof POWERS[0]) => {\n    setActive(power.id); setLoading(true); setResult(null);\n    try {\n      const r = await api.post(\"/kai/smart-chat\", { message: power.prompt, storeId });\n      setResult({ id: power.id, text: r.data?.data?.reply||r.data?.reply||\"Done\" });\n    } catch { toast.error(\"KIRO offline — add ANTHROPIC_API_KEY to Render\"); }\n    setLoading(false);\n  };\n  return (\n    <div style={{maxWidth:1000,margin:\"0 auto\"}}>\n      <motion.div initial={{opacity:0,y:-8}} animate={{opacity:1,y:0}} style={{marginBottom:24}}>\n        <div style={{display:\"inline-flex\",alignItems:\"center\",gap:8,padding:\"5px 14px\",borderRadius:99,background:\"rgba(107,53,232,0.1)\",border:\"1px solid rgba(107,53,232,0.2)\",marginBottom:12}}>\n          <Zap size={12} color={V.v400}/><span style={{fontSize:12,fontWeight:700,color:V.v300}}>KIRO Power Mode</span>\n        </div>\n        <h1 style={{fontSize:22,fontWeight:900,letterSpacing:\"-0.04em\",color:t.text,margin:\"0 0 4px\"}}>Deep Intelligence</h1>\n        <p style={{fontSize:13,color:t.muted,margin:0}}>Full-depth KIRO analysis — each takes 30-60 seconds but gives you real business intelligence</p>\n      </motion.div>\n      <div style={{display:\"grid\",gridTemplateColumns:\"repeat(3,1fr)\",gap:12,marginBottom:result?20:0}}>\n        {POWERS.map((p,i)=>(\n          <motion.div key={p.id} initial={{opacity:0,y:8}} animate={{opacity:1,y:0}} transition={{delay:i*0.06}}\n            onClick={()=>!loading&&run(p)} style={{padding:18,borderRadius:16,background:active===p.id?`rgba(107,53,232,0.1)`:t.card,border:`1px solid ${active===p.id?\"rgba(107,53,232,0.35)\":t.border}`,cursor:loading?\"not-allowed\":\"pointer\",transition:\"all 0.2s\"}}>\n            <div style={{fontSize:28,marginBottom:12}}>{p.icon}</div>\n            <p style={{fontSize:13,fontWeight:700,color:active===p.id?V.v300:t.text,margin:\"0 0 6px\"}}>{p.label}</p>\n            {active===p.id&&loading ? (\n              <div style={{display:\"flex\",alignItems:\"center\",gap:6}}><Loader2 size={11} style={{color:V.v400,animation:\"spin 1s linear infinite\"}}/><span style={{fontSize:11,color:V.v400}}>Thinking...</span></div>\n            ) : (\n              <p style={{fontSize:11,color:t.muted,margin:0,lineHeight:1.4}}>{p.prompt.slice(0,60)}...</p>\n            )}\n          </motion.div>\n        ))}\n      </div>\n      {result&&(\n        <motion.div initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} style={{padding:20,borderRadius:16,background:t.card,border:`1px solid ${t.border}`}}>\n          <div style={{display:\"flex\",alignItems:\"center\",gap:8,marginBottom:16}}>\n            <div style={{width:28,height:28,borderRadius:8,background:\"rgba(107,53,232,0.15)\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\"}}><Zap size={13} color={V.v400}/></div>\n            <span style={{fontSize:13,fontWeight:700,color:t.text}}>{POWERS.find(p=>p.id===result.id)?.label}</span>\n          </div>\n          <p style={{fontSize:13,lineHeight:1.75,color:t.muted,whiteSpace:\"pre-wrap\",margin:0}}>{result.text}</p>\n        </motion.div>\n      )}\n      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>\n    </div>\n  );\n}\n","frontend/src/app/dashboard/price-sync/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { useQuery, useMutation, useQueryClient } from \"@tanstack/react-query\";\nimport { motion } from \"framer-motion\";\nimport { useTheme } from \"../../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../../store/auth.store\";\nimport { api } from \"../../../lib/api\";\nimport { RefreshCw, Zap, TrendingUp, DollarSign, Loader2, Check } from \"lucide-react\";\nimport toast from \"react-hot-toast\";\nconst V = { v500:\"#6B35E8\", v400:\"#8B5CF6\", green:\"#10B981\", amber:\"#F59E0B\" };\nconst fmt = (n:number) => new Intl.NumberFormat(\"en-NG\",{style:\"currency\",currency:\"NGN\",maximumFractionDigits:0}).format(n||0);\nexport default function PriceSyncPage() {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const t = { card:isDark?\"#181230\":\"#fff\", border:isDark?\"rgba(255,255,255,0.07)\":\"rgba(107,53,232,0.08)\", text:isDark?\"#F0ECFF\":\"#130D2E\", muted:isDark?\"rgba(240,236,255,0.45)\":\"rgba(19,13,46,0.55)\", faint:isDark?\"rgba(255,255,255,0.03)\":\"rgba(107,53,232,0.03)\" };\n  const storeId = useAuthStore(s => s.user?.stores?.[0]?.id);\n  const qc = useQueryClient();\n  const [margin, setMargin] = useState(40);\n  const [syncing, setSyncing] = useState(false);\n  const { data } = useQuery({ queryKey:[\"products-price\",storeId], queryFn:()=>api.get(`/products/${storeId}?limit=20`).then(r=>r.data.data?.products||r.data.data||[]), enabled:!!storeId });\n  const products = data||[];\n  const syncAll = async () => {\n    setSyncing(true);\n    try {\n      await api.post(`/products/${storeId}/sync-prices`, { marginPct: margin });\n      toast.success(\"Prices synced with suppliers!\");\n      qc.invalidateQueries({queryKey:[\"products-price\"]});\n    } catch { toast.error(\"Sync failed — check supplier connections\"); }\n    setSyncing(false);\n  };\n  return (\n    <div style={{maxWidth:800,margin:\"0 auto\"}}>\n      <motion.div initial={{opacity:0,y:-8}} animate={{opacity:1,y:0}} style={{marginBottom:24}}>\n        <h1 style={{fontSize:22,fontWeight:900,letterSpacing:\"-0.04em\",color:t.text,margin:\"0 0 4px\"}}>Price Sync</h1>\n        <p style={{fontSize:13,color:t.muted,margin:0}}>Auto-sync your prices with supplier costs and apply a margin multiplier</p>\n      </motion.div>\n      <motion.div initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} style={{padding:20,borderRadius:16,background:t.card,border:`1px solid ${t.border}`,marginBottom:16}}>\n        <div style={{display:\"flex\",alignItems:\"center\",justifyContent:\"space-between\",flexWrap:\"wrap\",gap:12,marginBottom:16}}>\n          <div>\n            <p style={{fontSize:14,fontWeight:700,color:t.text,margin:\"0 0 4px\"}}>Target Margin</p>\n            <p style={{fontSize:12,color:t.muted,margin:0}}>KIRO will price all products at cost × (1 + {margin}%)</p>\n          </div>\n          <div style={{display:\"flex\",alignItems:\"center\",gap:12}}>\n            <input type=\"range\" min={10} max={200} value={margin} onChange={e=>setMargin(Number(e.target.value))} style={{width:120,accentColor:V.v500}}/>\n            <span style={{fontSize:18,fontWeight:900,color:V.v400,minWidth:48}}>{margin}%</span>\n          </div>\n        </div>\n        <button onClick={syncAll} disabled={syncing} style={{display:\"flex\",alignItems:\"center\",gap:8,padding:\"11px 22px\",borderRadius:12,background:`linear-gradient(135deg,${V.v500},#3D1C8A)`,border:\"none\",cursor:syncing?\"not-allowed\":\"pointer\",color:\"#fff\",fontSize:13,fontWeight:700,opacity:syncing?0.7:1}}>\n          {syncing?<Loader2 size={14} style={{animation:\"spin 1s linear infinite\"}}/>:<RefreshCw size={14}/>}\n          {syncing?\"Syncing prices...\":\"Sync All Prices\"}\n        </button>\n      </motion.div>\n      {products.length>0&&(\n        <div style={{borderRadius:16,overflow:\"hidden\",background:t.card,border:`1px solid ${t.border}`}}>\n          <div style={{display:\"grid\",gridTemplateColumns:\"1fr auto auto\",gap:12,padding:\"10px 16px\",borderBottom:`1px solid ${t.border}`}}>\n            <span style={{fontSize:11,fontWeight:700,textTransform:\"uppercase\",letterSpacing:\"0.08em\",color:t.muted}}>Product</span>\n            <span style={{fontSize:11,fontWeight:700,textTransform:\"uppercase\",letterSpacing:\"0.08em\",color:t.muted}}>Current</span>\n            <span style={{fontSize:11,fontWeight:700,textTransform:\"uppercase\",letterSpacing:\"0.08em\",color:t.muted}}>Synced</span>\n          </div>\n          {products.slice(0,8).map((p:any,i:number)=>{\n            const synced = Math.round((p.costPrice||p.price*0.6)*(1+margin/100));\n            return (\n              <div key={p.id} style={{display:\"grid\",gridTemplateColumns:\"1fr auto auto\",gap:12,alignItems:\"center\",padding:\"10px 16px\",borderBottom:i<7?`1px solid ${t.border}`:\"none\",background:i%2===0?\"transparent\":\"rgba(255,255,255,0.01)\"}}>\n                <p style={{fontSize:13,color:t.text,margin:0,overflow:\"hidden\",textOverflow:\"ellipsis\",whiteSpace:\"nowrap\"}}>{p.name}</p>\n                <p style={{fontSize:13,fontWeight:600,color:t.muted,margin:0,whiteSpace:\"nowrap\"}}>{fmt(p.price)}</p>\n                <p style={{fontSize:13,fontWeight:700,color:synced>p.price?V.green:V.amber,margin:0,whiteSpace:\"nowrap\"}}>{fmt(synced)}</p>\n              </div>\n            );\n          })}\n        </div>\n      )}\n      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>\n    </div>\n  );\n}\n","frontend/src/app/dashboard/replay/page.tsx":"\"use client\";\nimport { motion } from \"framer-motion\";\nimport { useTheme } from \"../../../components/layout/DashboardLayout\";\nimport { Zap, ArrowRight, MousePointer, Eye, Clock } from \"lucide-react\";\nimport Link from \"next/link\";\nconst V = { v500:\"#6B35E8\", v400:\"#8B5CF6\", v300:\"#A78BFA\" };\nexport default function ReplayPage() {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const t = { card:isDark?\"#181230\":\"#fff\", border:isDark?\"rgba(255,255,255,0.07)\":\"rgba(107,53,232,0.08)\", text:isDark?\"#F0ECFF\":\"#130D2E\", muted:isDark?\"rgba(240,236,255,0.45)\":\"rgba(19,13,46,0.55)\", faint:isDark?\"rgba(255,255,255,0.03)\":\"rgba(107,53,232,0.03)\" };\n  return (\n    <div style={{maxWidth:800,margin:\"0 auto\"}}>\n      <motion.div initial={{opacity:0,y:-8}} animate={{opacity:1,y:0}} style={{marginBottom:24}}>\n        <h1 style={{fontSize:22,fontWeight:900,letterSpacing:\"-0.04em\",color:t.text,margin:\"0 0 4px\"}}>Session Replay</h1>\n        <p style={{fontSize:13,color:t.muted,margin:0}}>Watch exactly how customers navigate your store</p>\n      </motion.div>\n      <div style={{padding:40,borderRadius:20,background:t.card,border:`1px solid ${t.border}`,textAlign:\"center\",marginBottom:16}}>\n        <div style={{width:64,height:64,borderRadius:20,background:\"rgba(107,53,232,0.1)\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\",margin:\"0 auto 16px\",fontSize:28}}>🎬</div>\n        <h2 style={{fontSize:18,fontWeight:800,color:t.text,margin:\"0 0 8px\",letterSpacing:\"-0.03em\"}}>Coming in Phase 2</h2>\n        <p style={{fontSize:13,color:t.muted,margin:\"0 0 24px\",maxWidth:400,marginLeft:\"auto\",marginRight:\"auto\",lineHeight:1.6}}>Session replay lets you watch real customer journeys — where they click, scroll, hesitate, and drop off. KIRO will automatically flag the moments that cost you sales.</p>\n        <Link href=\"/dashboard/kiro\" style={{display:\"inline-flex\",alignItems:\"center\",gap:8,padding:\"10px 20px\",borderRadius:12,background:`linear-gradient(135deg,${V.v500},#3D1C8A)`,textDecoration:\"none\",color:\"#fff\",fontSize:13,fontWeight:700}}>\n          <Zap size={13}/> Ask KIRO for analytics instead\n        </Link>\n      </div>\n      <div style={{display:\"grid\",gridTemplateColumns:\"repeat(3,1fr)\",gap:12}}>\n        {[{icon:Eye,label:\"Heatmaps\",desc:\"See where eyes and clicks go\"},{icon:MousePointer,label:\"Click tracking\",desc:\"Every tap mapped in real time\"},{icon:Clock,label:\"Session length\",desc:\"How long customers stay\"}].map((f,i)=>(\n          <div key={i} style={{padding:16,borderRadius:14,background:t.faint,border:`1px solid ${t.border}`}}>\n            <div style={{width:32,height:32,borderRadius:10,background:\"rgba(107,53,232,0.1)\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\",marginBottom:10}}><f.icon size={14} color={V.v400}/></div>\n            <p style={{fontSize:13,fontWeight:700,color:t.text,margin:\"0 0 4px\"}}>{f.label}</p>\n            <p style={{fontSize:12,color:t.muted,margin:0}}>{f.desc}</p>\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n"};
